. shared/feedback_render.go:formatAuditCommand
. shared/feedback_render.go:changedFlagArgs
. shared/feedback_render.go:redactAuditArgs
. shared/feedback_render.go:isSensitiveFlag
. shared/feedback_render.go:AddTimeFlag
. shared/feedback_render.go:timeFlagUsage
. shared/feedback_render.go:VerboseFlagUsage
